  "signal_basis": {
    "component_id": "C032.signal_basis",
    "value": "Account and schedule identifiers link events, drafts and publications are checked for shared lineage, and inspection yields an internally consistent history connecting draft versions to publication, with reported offline activity distinguished from logged events.",
