      "rationale": "These spans supply identifier linkage, lineage checks, continuity inspection, the consistent sequence and the observations' proposed status."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C032.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
